function equal(field,left,right) {
  const normalized=value=>field==='labelIds'&&Array.isArray(value)?[...new Set(value)].sort():value;
  return JSON.stringify(normalized(left))===JSON.stringify(normalized(right));
}
export function compareDraft(before,mine,latest) {
  const fields=Object.keys(mine).map(key=>{
    const localChanged=!equal(key,before[key],mine[key]),peerChanged=!equal(key,before[key],latest[key]);
    return {key,before:before[key],mine:mine[key],latest:latest[key],localChanged,peerChanged,conflict:localChanged&&peerChanged&&!equal(key,mine[key],latest[key])};
  });
  return {fields,conflicts:fields.filter(field=>field.conflict),dirty:fields.some(field=>field.localChanged)};
}
export function resolveDraft(comparison,choices={}) {
  const unresolved=comparison.conflicts.filter(field=>!['mine','latest'].includes(choices[field.key]));
  if(unresolved.length)throw new Error('Choose mine or latest for every overlapping field: '+unresolved.map(field=>field.key).join(', '));
  return Object.fromEntries(comparison.fields.map(field=>[field.key,field.conflict?(choices[field.key]==='mine'?field.mine:field.latest):field.localChanged?field.mine:field.latest]));
}
export function discardDraft(before,mine,confirmDiscard) {
  return !compareDraft(before,mine,before).dirty||confirmDiscard('Discard your unsaved changes?');
}

import {useState} from 'preact/hooks';
import {Button} from '../../components/ui.jsx';
import {compareDraft, resolveDraft} from '../../components/draft.js';
import {filterDraft} from './search-state.js';
const names = {name: 'Name', description: 'Description', query: 'Query', visibility: 'Visibility', teamId: 'Team'};
export function FilterComparison({before, draft, latest, teams, busy, onApply, onLoad}) {
  const [choices, setChoices] = useState({});
  const comparison = compareDraft(before, draft, filterDraft(latest));
  const unresolved = comparison.conflicts.some(field => !choices[field.key]);
  const display = (key, value) => key === 'teamId' ? teams.find(team => team.id === value)?.name ?? (value ? 'Shared team' : 'No team') : value || '(empty)';
  return <aside aria-label="Latest saved filter">
    <h3>Latest saved version · revision {latest.revision}</h3>
    <p>Your local draft has been retained. Independent edits are merged; choose every overlapping field. Applying choices changes only this draft. Save remains a separate action and checks the revision again.</p>
    {comparison.fields.filter(field => field.localChanged || field.peerChanged).map(field => <fieldset key={field.key} disabled={busy} aria-label={names[field.key] ?? field.key}>
      <legend>{names[field.key] ?? field.key}{field.conflict ? ' · overlapping edits' : field.localChanged ? ' · your edit' : ' · newer saved edit'}</legend>
      <dl><dt>Base</dt><dd><pre>{display(field.key, field.before)}</pre></dd><dt>Mine</dt><dd><pre>{display(field.key, field.mine)}</pre></dd><dt>Latest</dt><dd><pre>{display(field.key, field.latest)}</pre></dd></dl>
      {field.conflict && <>{['mine', 'latest'].map(choice => <label key={choice}><input type="radio" name={'filter-resolve-' + field.key} checked={choices[field.key] === choice} onChange={() => setChoices(previous => ({...previous, [field.key]: choice}))}/>{'Use ' + choice + ' for ' + (names[field.key] ?? field.key)}</label>)}</>}
    </fieldset>)}
    <Button type="button" disabled={busy || unresolved} onClick={() => onApply(resolveDraft(comparison, choices))}>{comparison.conflicts.length ? 'Apply selected field choices' : 'Keep my changes on latest version'}</Button>
    <Button type="button" disabled={busy} onClick={onLoad}>Load latest saved version</Button>
  </aside>;
}

import {useEffect, useLayoutEffect, useRef, useState} from 'preact/hooks';
import {Page, Button, Notice, Loading, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {createRequestGuard} from './request-guard.js';
import {createPlanningScope} from '../work/planning-actions.js';
import {useScopedLoad} from './scoped-load.js';
import {FilterForm} from './filter-form.jsx';
import {SearchResults} from './search-results.jsx';
import {previousSearchPage, nextSearchPage} from './search-state.js';

export function FilterDetailPage(props) {
  const owner = useRef({generation: 0});
  const identity = JSON.stringify([props.params.filterId, props.query.run]);
  if (owner.current.api !== props.api || owner.current.identity !== identity) owner.current = {api: props.api, identity, generation: owner.current.generation + 1};
  return <FilterResource key={owner.current.generation} {...props}/>;
}
function FilterResource({api, params, query, navigate}) {
  const id = params.filterId;
  const path = '/filters/' + encodeURIComponent(id);
  const [record, setRecord] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [results, setResults] = useState(null);
  const [history, setHistory] = useState(['']);
  const [editing, setEditing] = useState(null);
  const [unavailable, setUnavailable] = useState(false);
  const reads = useRef(createRequestGuard()).current;
  const actions = useRef(createPlanningScope()).current;
  const runs = useRef(createPlanningScope()).current;
  const discardRef = useRef(() => true);
  const editor = useRef(null);
  const alive = useRef(true);
  const options = useScopedLoad(record?.orgId ?? '', () => record ? api.get('/filters/options?orgId=' + encodeURIComponent(record.orgId)) : {teams: []});
  useLayoutEffect(() => () => {alive.current = false; editor.current = null; reads.invalidate(); actions.dispose(); runs.dispose();}, []);
  useEffect(() => {load();}, []);
  function lost(failure) {
    setError(failure); setResults(null); setHistory(['']);
    if ([401, 403, 404].includes(failure.status)) {setRecord(null); setUnavailable(true);}
  }
  async function load() {
    const ticket = reads.begin();
    setLoading(true); setError(null);
    try {
      const result = await api.get(path, {signal: ticket.signal});
      if (!reads.current(ticket)) return;
      setRecord(result.filter); setUnavailable(false);
      if (query.run === '1') run(['']);
    } catch (failure) {if (reads.current(ticket)) lost(failure);}
    finally {if (reads.current(ticket)) setLoading(false);}
  }
  async function run(nextHistory = ['']) {
    if (unavailable) return;
    const operation = runs.begin();
    if (!operation) return;
    reads.invalidate(); setLoading(false);
    setBusy(true); setError(null); setMessage('');
    try {
      const parameters = new URLSearchParams({limit: '25'});
      if (nextHistory.at(-1)) parameters.set('cursor', nextHistory.at(-1));
      const data = await api.get(path + '/search?' + parameters, {signal: operation.signal});
      if (!operation.current()) return;
      setRecord(data.filter); setResults(data); setHistory(nextHistory);
    } catch (failure) {if (operation.current()) lost(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  function closeEditor() {editor.current = null; setEditing(null);}
  async function openEditor(copy) {
    if (unavailable || !discardRef.current()) return;
    const operation = actions.begin();
    if (!operation) return;
    closeEditor(); setBusy(true); setError(null);
    try {
      const data = await api.get(path, {signal: operation.signal});
      if (!operation.current()) return;
      setRecord(data.filter);
      const source = copy ? {orgId: data.filter.orgId, name: data.filter.name.slice(0, 95) + ' copy', description: data.filter.description, query: data.filter.query, visibility: 'personal', teamId: ''} : data.filter;
      const form = {source, copy}; editor.current = form; setEditing(form);
    } catch (failure) {if (operation.current()) lost(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  async function remove() {
    if (unavailable || !discardRef.current()) return;
    const operation = actions.begin();
    if (!operation) return;
    setBusy(true); setError(null);
    try {
      await api.delete(path, undefined, {signal: operation.signal});
      if (!operation.current()) return;
      navigate('/filters?orgId=' + encodeURIComponent(record.orgId));
    } catch (failure) {if (operation.current()) lost(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  return <Page title={record?.name ?? 'Saved filter'} actions={<a href={routeLink('/filters', {orgId: record?.orgId})} onClick={event => {if (!discardRef.current()) event.preventDefault();}}>Saved filters</a>}>
    <Notice error={error}/><Notice>{message}</Notice>
    {loading && <Loading/>}
    {unavailable && <Notice>This saved filter is unavailable with your current access. Any local draft remains below; inaccessible records and results have been cleared.</Notice>}
    {record && <article aria-label="Saved filter details">
      <p>{record.description || 'No description'}</p><pre aria-label="Saved query">{record.query || 'All accessible issues'}</pre>
      <dl><dt>Visibility</dt><dd>{record.visibility === 'personal' ? 'Personal · only you' : 'Team shared'}</dd>
        {record.visibility === 'team' && <><dt>Team</dt><dd>{options.data?.teams.find(team => team.id === record.teamId)?.name ?? 'Shared team'}</dd></>}
        <dt>Creator</dt><dd>{record.canEdit ? 'Created by you' : 'Created by another team member'}</dd>
        <dt>Revision</dt><dd>{record.revision}</dd><dt>Created</dt><dd>{new Date(record.createdAt).toLocaleString()}</dd><dt>Updated</dt><dd>{new Date(record.updatedAt).toLocaleString()}</dd></dl>
      <p>Run always reads the currently saved query with your current access. A changed query can invalidate an older page cursor; run again to start at its first page.</p>
      <div className="actions"><Button busy={busy} onClick={() => run([''])}>Run filter</Button><Button disabled={busy} onClick={load}>Refresh saved filter</Button>
        <Button disabled={busy} onClick={() => openEditor(true)}>Create personal copy</Button>
        {record.canEdit && <><Button disabled={busy} onClick={() => openEditor(false)}>Edit saved filter</Button><ConfirmButton disabled={busy} message={'Delete saved filter “' + record.name + '”?'} onConfirm={remove}>Delete saved filter</ConfirmButton></>}
      </div>
    </article>}
    {editing && <FilterForm api={api} filter={editing.source} orgId={editing.source.orgId} copy={editing.copy} disabled={unavailable} teams={options.data?.teams} discardRef={discardRef}
      onCancel={closeEditor} onUnavailable={() => {reads.invalidate(); runs.dispose(); actions.dispose(); setBusy(false); setLoading(false); setRecord(null); setResults(null); setHistory(['']); setUnavailable(true);}}
      onSaved={filter => {
        if (!alive.current || editor.current !== editing) return;
        closeEditor(); setResults(null); setHistory(['']);
        if (editing.copy) navigate('/filters/' + encodeURIComponent(filter.id));
        else {setRecord(filter); setMessage('Saved “' + filter.name + '”.');}
      }}/>}
    {results && !unavailable && <section aria-label="Search results">
      <p>Results for <code>{results.filter.query || 'all accessible issues'}</code> · saved revision {results.filter.revision}</p>
      <SearchResults results={results} history={history} busy={busy} onPrevious={() => run(previousSearchPage(history))} onNext={() => run(nextSearchPage(history, results.nextCursor))}/>
    </section>}
  </Page>;
}

import {useLayoutEffect, useRef, useState} from 'preact/hooks';
import {Field, Button, Notice} from '../../components/ui.jsx';
import {compareDraft, discardDraft} from '../../components/draft.js';
import {createPlanningScope} from '../work/planning-actions.js';
import {filterDraft, filterPayload} from './search-state.js';
import {savedFilterInput} from '../../../../shared/src/index.js';
import {QueryEditor} from './query-editor.jsx';
import {FilterComparison} from './filter-comparison.jsx';

export function FilterForm(props) {
  const owner = useRef({generation: 0});
  if (owner.current.api !== props.api || owner.current.orgId !== props.orgId || owner.current.filter !== props.filter) owner.current = {api: props.api, orgId: props.orgId, filter: props.filter, generation: owner.current.generation + 1};
  return <FilterEditor key={owner.current.generation} {...props}/>;
}
function FilterEditor({api, filter, orgId, teams = [], onSaved, onCancel, onUnavailable, discardRef, copy = false, disabled = false}) {
  const [base, setBase] = useState(() => filterDraft(filter, orgId));
  const [draft, setDraft] = useState(base);
  const [busy, setBusy] = useState(false);
  const [revision, setRevision] = useState(filter?.revision);
  const [latest, setLatest] = useState(null);
  const [unavailable, setUnavailable] = useState(false);
  const [error, setError] = useState(null);
  const scope = useRef(createPlanningScope()).current;
  const queryRef = useRef(null);
  const currentDraft = useRef(draft);
  currentDraft.current = draft;
  const blocked = unavailable || disabled;
  const touched = compareDraft(base, draft, base).dirty;
  const canDiscard = () => discardDraft(base, currentDraft.current, message => globalThis.confirm(message));
  if (discardRef) discardRef.current = canDiscard;
  useLayoutEffect(() => {
    const closing = event => {if (compareDraft(base, currentDraft.current, base).dirty) {event.preventDefault(); event.returnValue = '';}};
    globalThis.addEventListener('beforeunload', closing);
    return () => {globalThis.removeEventListener('beforeunload', closing);};
  }, [base]);
  useLayoutEffect(() => () => {scope.dispose(); if (discardRef) discardRef.current = () => true;}, []);
  const update = (field, value) => {setDraft(previous => ({...previous, [field]: value})); setLatest(null);};
  const details = error?.details ?? {};
  function failed(failure) {
    setError(failure);
    if ([401, 403, 404].includes(failure.status)) {setUnavailable(true); setLatest(null); onUnavailable?.();}
  }
  async function save(event) {
    event.preventDefault();
    if (blocked) return;
    const operation = scope.begin();
    if (!operation) return;
    setError(null); setBusy(true);
    try {
      const payload = filterPayload(draft, revision);
      const {expectedRevision, ...validated} = payload;
      savedFilterInput(validated);
      if (draft.visibility === 'team' && !draft.teamId) throw new Error('Choose a team to share this filter');
      const result = filter?.id ? await api.patch('/filters/' + encodeURIComponent(filter.id), payload, {signal: operation.signal}) : await api.post('/filters', payload, {signal: operation.signal});
      if (!operation.current()) return;
      setBase(filterDraft(result.filter)); setDraft(filterDraft(result.filter));
      onSaved(result.filter);
    } catch (failure) {if (operation.current()) failed(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  async function inspectLatest() {
    if (blocked) return;
    const operation = scope.begin();
    if (!operation) return;
    setBusy(true);
    try {
      const result = await api.get('/filters/' + encodeURIComponent(filter.id), {signal: operation.signal});
      if (!operation.current()) return;
      setLatest(result.filter);
    } catch (failure) {if (operation.current()) failed(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  function acceptLatest(values) {
    setBase(filterDraft(latest)); setDraft(values); setRevision(latest.revision); setLatest(null); setError(null);
  }
  function loadLatest() {
    if (touched && !globalThis.confirm('Replace your unsaved draft with the latest saved filter?')) return;
    acceptLatest(filterDraft(latest));
  }
  function cancel() {if (canDiscard()) onCancel();}
  return <form className="filter-form" onSubmit={save}>
    <h2>{copy ? 'Create a personal copy' : filter?.id ? 'Edit saved filter' : 'Save this search'}</h2>
    <Notice error={error}/>
    {blocked && <Notice>This filter is no longer editable with your current access. Your draft remains here so you can read it before closing.</Notice>}
    {error?.status === 409 && filter?.id && !blocked && <Button type="button" busy={busy} onClick={inspectLatest}>Inspect latest saved version</Button>}
    {latest && <FilterComparison key={JSON.stringify([base, draft, latest])} before={base} draft={draft} latest={latest} teams={teams} busy={busy} onApply={acceptLatest} onLoad={loadLatest}/>}
    {revision != null && <p>Editing revision {revision}{touched ? ' · unsaved changes' : ''}</p>}
    <fieldset disabled={busy || blocked}>
      <legend>Saved filter fields</legend>
      <Field label="Name" error={details.name} value={draft.name} required maxLength={100} onInput={event => update('name', event.currentTarget.value)}/>
      <Field label="Description" error={details.description}><textarea value={draft.description} maxLength={1000} onInput={event => update('description', event.currentTarget.value)}/></Field>
      <QueryEditor api={api} orgId={orgId} value={draft.query} inputRef={queryRef} error={error} label="Saved filter query" id="saved-filter-query" testId="saved-filter-query" onChange={value => update('query', value)}/>
      <Field label="Visibility" error={details.visibility}><select value={draft.visibility} onChange={event => update('visibility', event.currentTarget.value)}>
        <option value="personal">Personal · only you</option><option value="team">Shared with a team</option>
      </select></Field>
      {draft.visibility === 'team' && <Field label="Team" error={details.teamId}><select required value={draft.teamId} onChange={event => update('teamId', event.currentTarget.value)}>
        <option value="">Choose one of your teams</option>{teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select>{!teams.length && <p>Join a team in this organization before sharing a filter.</p>}</Field>}
    </fieldset>
    <p>Every run uses the current viewer’s project access. Only the creator can edit or delete a filter.</p>
    <div className="actions"><Button busy={busy} disabled={blocked} type="submit">Save filter</Button><Button type="button" onClick={cancel}>Cancel</Button></div>
  </form>;
}

import {useEffect, useLayoutEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {EntityPicker} from './selectors.jsx';
import {FilterForm} from './filter-form.jsx';
import {useScopedLoad} from './scoped-load.js';
import {createRequestGuard} from './request-guard.js';
import {createPlanningScope} from '../work/planning-actions.js';

export function FiltersPage(props) {
  const owner = useRef({generation: 0});
  if (owner.current.api !== props.api || owner.current.orgId !== props.query.orgId) owner.current = {api: props.api, orgId: props.query.orgId, generation: owner.current.generation + 1};
  return <FiltersOrganization key={owner.current.generation} {...props}/>;
}
function FiltersOrganization({api, query}) {
  const organizations = useLoad(() => api.get('/insight/options?type=organizations&limit=1'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const discardRef = useRef(() => true);
  useEffect(() => {if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);}, [organizations.data]);
  function changeOrg(value) {if (value !== orgId && discardRef.current()) setOrgId(value);}
  return <Page title="Saved filters" actions={<a href={routeLink('/search', {orgId})} onClick={event => {if (!discardRef.current()) event.preventDefault();}}>Search issues</a>}>
    <Notice error={organizations.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Join an organization before saving a filter.</Empty> : <>
      <EntityPicker api={api} type="organizations" label="Organization" value={orgId} required onChange={changeOrg}/>
      <FiltersScope key={orgId} api={api} orgId={orgId} discardRef={discardRef}/>
    </>}
  </Page>;
}
function FiltersScope({api, orgId, discardRef}) {
  const [visibility, setVisibility] = useState('all');
  const [nameQuery, setNameQuery] = useState('');
  const [owned, setOwned] = useState(false);
  const [teamId, setTeamId] = useState('');
  const [cursors, setCursors] = useState(['']);
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const editor = useRef(null);
  const alive = useRef(true);
  const pendingEdit = useRef(null);
  const editGuard = useRef(createRequestGuard()).current;
  const mutations = useRef(createPlanningScope()).current;
  const options = useScopedLoad(orgId, () => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: []});
  const view = JSON.stringify([orgId, visibility, nameQuery, owned, teamId, cursors.at(-1)]);
  const listing = useScopedLoad(view, () => orgId ? api.get('/filters?' + new URLSearchParams({orgId, visibility, q: nameQuery, owned: String(owned), teamId, limit: '25', cursor: cursors.at(-1)})) : {items: [], total: 0});
  useLayoutEffect(() => () => {alive.current = false; editor.current = null; editGuard.invalidate(); mutations.dispose(); discardRef.current = () => true;}, []);
  function setEditor(value) {editor.current = value; setEditing(value);}
  function replaceEditor(value) {
    if (!discardRef.current()) return;
    editGuard.invalidate(); pendingEdit.current = null; setEditor(value);
  }
  async function remove(filter) {
    const operation = mutations.begin();
    if (!operation) return;
    setError(null); setBusy(true);
    try {
      await api.delete('/filters/' + encodeURIComponent(filter.id), undefined, {signal: operation.signal});
      if (!operation.current()) return;
      if (editor.current?.id === filter.id) setEditor(null);
      setMessage('Deleted “' + filter.name + '”.'); setCursors(['']); listing.reload();
    } catch (failure) {if (operation.current()) {setError(failure); if ([401, 403, 404].includes(failure.status)) listing.reload();}}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  async function edit(filter) {
    if (pendingEdit.current === filter.id || !discardRef.current()) return;
    setEditor(null); setError(null); pendingEdit.current = filter.id;
    const ticket = editGuard.begin();
    try {
      const result = await api.get('/filters/' + encodeURIComponent(filter.id), {signal: ticket.signal});
      if (editGuard.current(ticket)) setEditor(result.filter);
    } catch (failure) {if (editGuard.current(ticket)) {setError(failure); if ([401, 403, 404].includes(failure.status)) listing.reload();}}
    finally {if (editGuard.current(ticket)) pendingEdit.current = null;}
  }
  function follow(event) {if (!discardRef.current()) event.preventDefault();}
  return <>
    <Notice error={error ?? listing.error ?? options.error}/><Notice>{message}</Notice>
    <div className="search-controls">
      <Field label="Find a saved filter"><input value={nameQuery} maxLength={100} placeholder="Name or description" onInput={event => {setNameQuery(event.currentTarget.value); setCursors(['']);}}/></Field>
      <Field label="Visibility"><select value={visibility} onChange={event => {setVisibility(event.currentTarget.value); setCursors(['']);}}>
        <option value="all">Personal and shared</option><option value="personal">Personal</option><option value="team">Team shared</option>
      </select></Field>
      <Field label="Team"><select value={teamId} onChange={event => {setTeamId(event.currentTarget.value); setCursors(['']);}}>
        <option value="">All my teams</option>{options.data?.teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select></Field>
      <label><input type="checkbox" checked={owned} onChange={event => {setOwned(event.currentTarget.checked); setCursors(['']);}}/>Created by me</label>
    </div>
    <Button disabled={!orgId || busy || listing.loading} onClick={listing.reload}>Refresh filters</Button>
    <Button disabled={!orgId || busy || Boolean(options.error)} onClick={() => replaceEditor({})}>Create saved filter</Button>
    {editing && <FilterForm api={api} orgId={orgId} filter={editing} teams={options.data?.teams} discardRef={discardRef}
      onCancel={() => setEditor(null)} onUnavailable={listing.reload} onSaved={filter => {
        if (!alive.current || editor.current !== editing) return;
        setEditor(null); setMessage('Saved “' + filter.name + '”.'); setCursors(['']); listing.reload();
      }}/>}
    {listing.loading ? <Loading/> : listing.error ? null : !listing.data?.items.length ? <Empty>No saved filters in this view. Create one or ask a teammate to share one.</Empty> : <>
      <p>{listing.data.total} accessible filters</p>
      <ul className="saved-filters">{listing.data.items.map(filter => <li key={filter.id}>
        <article><h2><a href={routeLink('/filters/' + encodeURIComponent(filter.id))} onClick={follow}>{filter.name}</a></h2>
          {filter.description && <p>{filter.description}</p>}<p>Updated {new Date(filter.updatedAt).toLocaleString()}</p>
          <pre>{filter.query || 'All accessible issues'}</pre>
          <p>{filter.visibility === 'personal' ? 'Personal' : 'Team: ' + (options.data?.teams.find(team => team.id === filter.teamId)?.name ?? 'Shared team')} · revision {filter.revision}</p>
          <div className="actions"><a className="button" href={routeLink('/filters/' + encodeURIComponent(filter.id), {run: '1'})} onClick={follow}>Run filter</a>
            {filter.canEdit && <><Button disabled={busy} onClick={() => edit(filter)}>Edit</Button>
              <ConfirmButton disabled={busy} message={'Delete saved filter “' + filter.name + '”?'} onConfirm={() => {if (discardRef.current()) remove(filter);}}>Delete</ConfirmButton></>}
          </div>
        </article>
      </li>)}</ul>
      <div className="actions"><Button disabled={busy || cursors.length < 2} onClick={() => setCursors(previous => previous.slice(0, -1))}>Previous</Button>
        <span>Page {cursors.length}</span><Button disabled={busy || !listing.data.nextCursor} onClick={() => setCursors(previous => [...previous, listing.data.nextCursor])}>Next</Button></div>
    </>}
  </>;
}

import {useEffect, useRef, useState} from 'preact/hooks';
import {Field, Notice} from '../../components/ui.jsx';
import {validatedQuery} from '../../../../shared/src/index.js';
import {errorPosition} from './search-state.js';

export function QueryEditor({api, orgId, projectId, value, onChange, inputRef, error, label = 'Search query', id = 'query', testId = 'search-query'}) {
  const [items, setItems] = useState([]);
  const [active, setActive] = useState(-1);
  const [open, setOpen] = useState(false);
  const [caret, setCaret] = useState(value.length);
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState(null);
  const listId = id + '-completions';
  const focused = useRef(false);
  let syntaxError = null;
  try {validatedQuery(value);} catch (invalid) {syntaxError = invalid;}
  const position = errorPosition(error ?? syntaxError);
  useEffect(() => {
    if (!orgId) {setItems([]); setBusy(false); return;}
    let current = true;
    const abort = new AbortController();
    const timer = setTimeout(async () => {
      setBusy(true);
      const params = new URLSearchParams({orgId, q: value, caret: String(Math.min(caret, value.length))});
      if (projectId) params.set('projectId', projectId);
      try {
        const result = await api.get('/search/suggestions?' + params, {signal: abort.signal});
        if (!current) return;
        setItems(result.items);
        setActive(-1);
        setFailure(null);
        setOpen(focused.current && result.items.length > 0);
      } catch (invalid) {
        if (!current || abort.signal.aborted) return;
        setItems([]);
        setFailure(invalid);
      } finally {if (current) setBusy(false);}
    }, 180);
    return () => {current = false; clearTimeout(timer); abort.abort();};
  }, [api, orgId, projectId, value, caret]);
  useEffect(() => {
    const form = inputRef.current?.form;
    const submitted = () => setOpen(false);
    const focusedElsewhere = event => {
      if (event.target !== inputRef.current && event.target.form !== form) setOpen(false);
    };
    form?.addEventListener('submit', submitted);
    document.addEventListener('focusin', focusedElsewhere);
    return () => {
      form?.removeEventListener('submit', submitted);
      document.removeEventListener('focusin', focusedElsewhere);
    };
  }, [inputRef]);
  function complete(item) {
    onChange(item.query);
    setOpen(false);
    setActive(-1);
    const nextCaret = item.start + item.replacement.length;
    setCaret(nextCaret);
    queueMicrotask(() => {
      inputRef.current?.focus();
      inputRef.current?.setSelectionRange(nextCaret, nextCaret);
    });
  }
  function keyboard(event) {
    if (event.key === 'Escape') {setOpen(false); setActive(-1); return;}
    if (!items.length) return;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setOpen(true);
      setActive(previous => (previous + 1) % items.length);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setOpen(true);
      setActive(previous => previous <= 0 ? items.length - 1 : previous - 1);
    } else if ((event.key === 'Enter' || event.key === 'Tab') && open && active >= 0) {
      event.preventDefault();
      complete(items[active]);
    }
  }
  function trackCaret(event) {setCaret(event.currentTarget.selectionStart ?? value.length);}
  return <div className="query-editor">
    <Field label="Query" error={error?.details?.query}>
      <input ref={inputRef} data-testid={testId} aria-label={label} role="combobox"
        aria-autocomplete="list" aria-controls={listId} aria-expanded={open}
        aria-activedescendant={open && active >= 0 ? id + '-option-' + active : undefined}
        aria-describedby={id + '-editor-help'} aria-invalid={Boolean(error)}
        value={value} maxLength={4000} spellCheck={false}
        onInput={event => {onChange(event.currentTarget.value); trackCaret(event);}}
        onSelect={trackCaret} onKeyDown={keyboard}
        onFocus={() => {focused.current = true; setOpen(items.length > 0);}}
        onBlur={event => {
          focused.current = false;
          if (!event.relatedTarget || event.relatedTarget.form !== inputRef.current?.form) setOpen(false);
        }}/>
    </Field>
    <p id={id + '-editor-help'}>Type a field such as status: for accessible values. Arrow keys choose a suggestion; Enter or Tab inserts it. Escape closes the list.</p>
    {position && <p role={error ? 'alert' : 'status'} className="query-position">
      {error?.message ?? syntaxError?.message} · {position.description}
      <button type="button" onClick={() => {inputRef.current.focus(); inputRef.current.setSelectionRange(position.offset, position.end);}}>Select query position</button>
    </p>}
    {!syntaxError && <p role="status">{value.trim() ? 'Query syntax is valid.' : 'An empty query includes all accessible issues.'}</p>}
    <Notice error={failure}/>
    <p role="status">{busy ? 'Loading suggestions…' : items.length + ' suggestions available'}</p>
    {open && <ul id={listId} role="listbox" aria-label="Query suggestions" className="query-options">
      {items.map((item, index) => <li key={item.replacement} id={id + '-option-' + index} role="option" aria-selected={active === index}>
        <button type="button" tabIndex={-1} onMouseDown={event => event.preventDefault()} onClick={() => complete(item)}>
          <strong>{item.label}</strong><span>{item.description}</span>
        </button>
      </li>)}
    </ul>}
    {!open && items.length > 0 && <button type="button" onClick={() => {inputRef.current.focus(); setOpen(true);}}>Show query suggestions</button>}
  </div>;
}

